INSERT INTO `achievement_criteria`(`achievement_id`,`component_type`,`component_id`,`event_type`,`progress_mode`,`behavior`,`target_id`,`target_id2`,`target_value`,`required_count`,`enabled`) SELECT e.`achievement_id`,e.`component_type`,e.`component_id`,e.`event_type`,e.`progress_mode`,e.`behavior`,e.`target_id`,e.`target_id2`,e.`target_value`,e.`required_count`,e.`enabled` FROM `_dragonscale_achievement_criteria` e LEFT JOIN `achievement_criteria` a ON a.`achievement_id`<=>e.`achievement_id` AND a.`component_type`<=>e.`component_type` AND a.`component_id`<=>e.`component_id` WHERE a.`achievement_id` IS NULL;
